export function getProviderLogo(credId: string): LogoEntry | undefined {
  if (LOGO_DATA[credId]) return LOGO_DATA[credId];
  // Strip the common runtime suffixes the backend tacks on to BYOK ids,
  // so e.g. `openai_api_key` / `notion_token` / `gmail_oauth` resolve to
  // the provider's logo.
  const bare = credId.replace(/_(api_key|api|key|token|oauth)$/i, "");
  if (bare !== credId && LOGO_DATA[bare]) return LOGO_DATA[bare];
  // Prefix match — keeps `zoho_crm`, `aws_s3_bucket` etc. mapped to the
  // longest matching provider key. Iterate longest-first so `googleads`
  // doesn't lose to `google`.
  const keys = Object.keys(LOGO_DATA).sort((a, b) => b.length - a.length);
  for (const key of keys) {
    if (credId === key || credId.startsWith(key + "_")) return LOGO_DATA[key];
  }
  // Last resort: normalised equality (handles credId `Slack`, `slack-api`, etc.).
  const norm = credId.toLowerCase().replace(/[^a-z0-9]/g, "");
  for (const [key, val] of Object.entries(LOGO_DATA)) {
    if (key.toLowerCase().replace(/[^a-z0-9]/g, "") === norm) return val;
  }
  return undefined;
}
